    private void FindReplaceDialog()
    {
        if(textEditor==null)return;var editor=textEditor;var find=Ui.Input(editor.SelectedText);var replace=Ui.Input();var matchCase=new CheckBox{Content="区分大小写"};var regex=new CheckBox{Content="正则表达式"};var whole=new CheckBox{Content="全字匹配"};var message=Ui.Text("",11,"#AA8960");
        Regex Pattern(){var pattern=regex.IsChecked==true?find.Text:Regex.Escape(find.Text);if(whole.IsChecked==true)pattern=@"\b(?:"+pattern+@")\b";return new(pattern,matchCase.IsChecked==true?RegexOptions.None:RegexOptions.IgnoreCase,TimeSpan.FromMilliseconds(200));}
        void Run(Action action){try{if(find.Text.Length==0)return;action();}catch(Exception e)when(e is ArgumentException or RegexMatchTimeoutException){message.Text="正则表达式无效或匹配超时";}}
        var next=Ui.Button("查找下一个",()=>Run(()=>{var pattern=Pattern();var start=Math.Min(editor.SelectionStart+Math.Max(editor.SelectionLength,1),editor.Text.Length);var match=pattern.Match(editor.Text,start);if(!match.Success)match=pattern.Match(editor.Text);if(match.Success){editor.Select(match.Index,match.Length);editor.ScrollTo(editor.Document.GetLocation(match.Index).Line,1);message.Text="已定位匹配项";}else message.Text="没有找到匹配内容";}));var one=Ui.Button("替换所选",()=>Run(()=>{if(Pattern().IsMatch(editor.SelectedText))editor.SelectedText=regex.IsChecked==true?Pattern().Replace(editor.SelectedText,replace.Text):replace.Text;}));var all=Ui.Button("全部替换",()=>Run(()=>{var pattern=Pattern();var count=pattern.Matches(editor.Text).Count;var text=regex.IsChecked==true?pattern.Replace(editor.Text,replace.Text):pattern.Replace(editor.Text,_=>replace.Text);editor.Document.Replace(0,editor.Document.TextLength,text);message.Text=$"已替换 {count} 处";}),true);var content=Ui.Stack(Ui.Field("查找",find),Ui.Field("替换为",replace),Ui.Row(matchCase,Ui.Spaced(regex,new Thickness(17,0,17,0)),whole),Ui.Spaced(Ui.Row(next,Ui.Spaced(one,new Thickness(8,0,8,0)),all),new Thickness(0,15,0,14)),message);content.Margin=new Thickness(25);var dialog=Ui.Dialog(this,"查找与替换",content,570);dialog.Loaded+=(_,_)=>find.Focus();dialog.ShowDialog();
    }
    private void OutlineDialog()
