    private void InsertLink()
    {var url=Ui.Input("https://");var label=Ui.Input(textEditor?.SelectedText??"");var content=Ui.Stack(Ui.Field("显示文字",label),Ui.Field("链接地址",url));content.Margin=new Thickness(25);Window? dialog=null;content.Children.Add(Ui.Button("插入",()=>{if(!Uri.TryCreate(url.Text,UriKind.Absolute,out var uri)||uri.Scheme is not("http" or "https"))return;Wrap("["+(label.Text.Length>0?label.Text:"链接")+"]("+url.Text.Replace(")","%29")+")","","");dialog!.Close();},true));dialog=Ui.Dialog(this,"插入链接",content);dialog.ShowDialog();}
    private void InsertImage()
    {var open=new OpenFileDialog{Filter="图片|*.png;*.jpg;*.jpeg;*.gif;*.webp;*.bmp"};if(open.ShowDialog(this)!=true)return;try{var file=new FileInfo(open.FileName);if(file.Length>2_000_000)throw new InvalidDataException("单张图片请控制在 2 MB 以内");var ext=file.Extension.ToLowerInvariant();var mime=ext is ".jpg" or ".jpeg"?"jpeg":ext.TrimStart('.');Wrap($"![{file.Name}](data:image/{mime};base64,{Convert.ToBase64String(File.ReadAllBytes(file.FullName))})","","");}catch(Exception error){Toast(error.Message);}}
    private void EmbedBitmap(BitmapSource bitmap){try{var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var stream=new MemoryStream();encoder.Save(stream);if(stream.Length>2_000_000)throw new InvalidDataException("粘贴图片请控制在 2 MB 以内");Wrap("![粘贴图片](data:image/png;base64,"+Convert.ToBase64String(stream.ToArray())+")","","");}catch(Exception e){Toast(e.Message);}}
    private void ExportNote(Note note){var save=new SaveFileDialog{Filter="Markdown|*.md|普通文本|*.txt|富文本|*.rtf",FileName=RecordTools.SafeName(note.Title)+".md"};if(save.ShowDialog(this)!=true)return;if(save.FilterIndex==3){var doc=MarkdownDocument.Render(note.Content);using var stream=File.Create(save.FileName);new TextRange(doc.ContentStart,doc.ContentEnd).Save(stream,DataFormats.Rtf);}else File.WriteAllText(save.FileName,note.Content);Toast("记录已导出");}
    private void PrintNote(Note note){var dialog=new PrintDialog();if(dialog.ShowDialog()!=true)return;var document=MarkdownDocument.Render("# "+note.Title+"\n\n"+note.Content);document.PageWidth=dialog.PrintableAreaWidth;document.PageHeight=dialog.PrintableAreaHeight;document.ColumnWidth=dialog.PrintableAreaWidth;dialog.PrintDocument(((IDocumentPaginatorSource)document).DocumentPaginator,note.Title);}
    private async Task ImportFiles()
    {
        var open=new OpenFileDialog{Filter="文本与墨记备份|*.md;*.markdown;*.txt;*.moji;*.mojibak;*.json",Multiselect=true};if(open.ShowDialog(this)!=true)return;
        try{foreach(var path in open.FileNames){if(new FileInfo(path).Length>30_000_000)throw new InvalidDataException("导入文件请控制在 30 MB 以内");if(new[]{".moji",".mojibak",".json"}.Contains(Path.GetExtension(path).ToLowerInvariant())){var envelope=await VaultStore.ReadEnvelope(path);var password=AskPassword("备份的主密码");if(password==null)continue;using var key=await Task.Run(()=>CryptoService.Derive(password,envelope.Salt,envelope.Iterations));var backup=await Task.Run(()=>CryptoService.Decrypt<Workspace>(envelope,key));backup.Validate();var merged=WorkspaceMerge.Merge(VM.State!,new(1,backup.Id,backup.Notebooks,backup.Notes),new Dictionary<string,string>());VM.Change(v=>v with{Notebooks=merged.Notebooks,Notes=merged.Notes});}else{var book=VM.State!.LiveBooks.FirstOrDefault(b=>b.Id==VM.View&&b.Mode!=NoteMode.Password)??VM.State.LiveBooks.FirstOrDefault(b=>b.Mode==NoteMode.Text);if(book==null){book=new(){Name="导入文本"};var created=book;VM.Change(v=>v with{Notebooks=[..v.Notebooks,created]});}var note=new Note{NotebookId=book.Id,Title=Path.GetFileNameWithoutExtension(path),Content=await File.ReadAllTextAsync(path)};VM.Change(v=>v with{Notes=[..v.Notes,note]});Navigate(book.Id,note.Id);}}Toast("导入完成");}catch(Exception error){Toast(error.Message);}
    }
    private async Task ExportBackup()
    {if(VM.State==null||VM.Key==null){Toast("演示空间不导出加密备份");return;}var save=new SaveFileDialog{Filter="墨记加密备份|*.moji",FileName=$"墨记-加密备份-{DateTime.Now:yyyy-MM-dd}.moji"};if(save.ShowDialog(this)!=true)return;try{await VM.SaveAsync();await VM.Store.ExportAsync(VM.State,VM.Key,save.FileName);Toast("加密备份已导出");}catch(Exception e){Toast(e.Message);}}
    private void ExportAllMarkdown(){var save=new SaveFileDialog{Filter="Markdown 压缩包|*.zip",FileName=$"墨记-文本集-{DateTime.Now:yyyy-MM-dd}.zip"};if(save.ShowDialog(this)!=true)return;try{if(File.Exists(save.FileName))File.Delete(save.FileName);RecordTools.ExportMarkdown(VM.State!,save.FileName);Toast("文本集已导出，不包含密码库");}catch(Exception e){Toast(e.Message);}}
    private void OpenUrl(string value){if(Uri.TryCreate(value,UriKind.Absolute,out var uri)&&uri.Scheme is "https" or "http")Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});else Toast("请填写有效的 http 或 https 地址");}
    private void PasswordAudit()
    {var notes=VM.State!.LiveNotes.Where(n=>VM.State.Notebooks.First(b=>b.Id==n.NotebookId).Mode==NoteMode.Password&&n.Password.Length>0).ToList();var weak=notes.Where(n=>RecordTools.Strength(n.Password)<2).ToList();var duplicate=notes.Where(n=>notes.Any(other=>other.Id!=n.Id&&other.Password==n.Password)).ToList();var panel=Ui.Stack(Ui.Text($"{weak.Count} 个密码需要加强   ·   {duplicate.Count} 个账号使用重复密码",14));panel.Margin=new Thickness(25);Window? dialog=null;foreach(var note in weak.Concat(duplicate).DistinctBy(n=>n.Id)){var b=Ui.Button("⚿  "+note.Title,()=>{dialog!.Close();Navigate(note.NotebookId,note.Id);});b.Margin=new Thickness(0,12,0,0);panel.Children.Add(b);}if(weak.Count+duplicate.Count==0)panel.Children.Add(Ui.Spaced(Ui.Text("目前没有发现弱密码或重复密码。",12,"#8AA273"),new Thickness(0,22,0,10)));dialog=Ui.Dialog(this,"密码健康检查",panel,620);dialog.ShowDialog();}
